using System;
using MassTransit;

public class OrderStateMachine : MassTransitStateMachine<OrderState>
{
    public OrderStateMachine()
    {
        InstanceState(x => x.CurrentState);

        Event(() => OrderReceived); // from Shop API
        Event(() => StockReserved); // from Warehouse service
        Event(() => StockUnavailable); // from Warehouse service
        Event(() => PaymentCharged); // from Payment service
        Event(() => PaymentFailed); // from Payment service
        Event(() => OrderShipped); // from Warehouse service
        Event(() => PaymentTimeout);

        Initially(
            When(OrderReceived)
                .TransitionTo(ReservingStock));

        During(ReservingStock,
            When(StockReserved)
                .TransitionTo(ChargingPayment),
            When(StockUnavailable)
                .Finalize());

        During(ChargingPayment,
            When(PaymentCharged)
                .TransitionTo(Shipping),
            When(PaymentFailed, context => true /* TODO guard: attempts >= 3 */)
                .Finalize(),
            When(PaymentFailed, context => true /* TODO guard: attempts < 3 */)
                .TransitionTo(ChargingPayment),
            When(PaymentTimeout)
                .Finalize());

        During(Shipping,
            When(OrderShipped)
                .Finalize(),
            Ignore(PaymentCharged));

        WhenEnter(ReservingStock, binder => binder
            .Send(context => new ReserveStock { CorrelationId = context.Saga.CorrelationId /* TODO: set the other properties */ }));

        WhenEnter(ChargingPayment, binder => binder
            .Send(context => new ChargePayment { CorrelationId = context.Saga.CorrelationId /* TODO: set the other properties */ }));

        WhenEnter(Shipping, binder => binder
            .Send(context => new ShipOrder { CorrelationId = context.Saga.CorrelationId /* TODO: set the other properties */ })
            .Publish(context => new OrderAccepted { CorrelationId = context.Saga.CorrelationId /* TODO: set the other properties */ }));

        SetCompletedWhenFinalized();
    }

    public State ReservingStock { get; private set; } = null!;
    public State ChargingPayment { get; private set; } = null!;
    public State Shipping { get; private set; } = null!;

    public Event<OrderReceived> OrderReceived { get; private set; } = null!;
    public Event<StockReserved> StockReserved { get; private set; } = null!;
    public Event<StockUnavailable> StockUnavailable { get; private set; } = null!;
    public Event<PaymentCharged> PaymentCharged { get; private set; } = null!;
    public Event<PaymentFailed> PaymentFailed { get; private set; } = null!;
    public Event<OrderShipped> OrderShipped { get; private set; } = null!;
    public Event<PaymentTimeout> PaymentTimeout { get; private set; } = null!;
}
